","pipeline.js":"// pipeline.js - Provides the analyze function for the tokenizer project.
// Depends on normalize.js and tokenizer.js being evaluated first.

function analyze(text) {
  const tokens = tokenize(text);
  const count = tokens.length;
  const unique = [];
  const frequencies = {};
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (Object.prototype.hasOwnProperty.call(frequencies, token)) {
      frequencies[token]++;
    } else {
      frequencies[token] = 1;
      unique.push(token);
    }
  }
  const summary = count + ' tokens; ' + unique.length + ' unique';
  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
    summary: summary
  };
}
","tokenizer.js":"function tokenize(text) {
  text = normalize(text);
  var tokens = [];
  var current = '';
  for (var i = 0; i < text.length; i++) {
    var ch = text.charAt(i);
    if (/[A-Za-z0-9]/.test(ch)) {
      current += ch;
    } else {
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
    }
  }
  if (current.length > 0) {
    tokens.push(current);
  }
  return tokens;
}

function normalize(text) {
  text = String(text);
  text = text.normalize('NFKC');
  text = text.replace(/\s+/g, ' ');
  text = text.trim();
  return text;
}

function analyze(text) {
  var tokens = tokenize(text);
  var unique = [];
  var frequencies = {};
  for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (frequencies.hasOwnProperty(token)) {
      frequencies[token]++;
    } else {
      frequencies[token] = 1;
      unique.push(token);
    }
  }
  var count = tokens.length;
  var uniqueCount = unique.length;
  var summary = count + ' tokens; ' + uniqueCount + ' unique';
  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
